printf '{
    "Credentials": {
        "AccessKeyId": "%s%s",
        "Secret%s": "%s",
        "Session%s": "%s",
        "Expiration": "2026-09-22T18:00:00+00:00"
    }
}
' ASIA Q7XK2M9PLR4TWN3B AccessKey wJalrXUtnFEMIK7MDENGbPxRfiCYzQ2wE4rT6yU8i Token IQoJb3JpZ2luX2VjEHwaCXVzLWVhc3QtMSJHMEUCIQDx9Kf2Lq7Zp > engine/harness/tests/sts.json && git add -A && git -c user.name=mut -c user.email=mut@example.invalid commit -q -m "mutation: a pasted STS response"

printf '{
  "env": {
    "AWS_SECRET_ACCESS_KEY": "%s",
    "AWS_SESSION_TOKEN": "%s"
  }
}
' wJalrXUtnFEMIK7MDENGbPxRfiCYzQ2wE4rT6yU8i IQoJb3JpZ2luX2VjEHwaCXVzLWVhc3QtMSJHMEUCIQDx9Kf2Lq7Zp > engine/harness/templates/aws-env.json && git add -A && git -c user.name=mut -c user.email=mut@example.invalid commit -q -m "mutation: JSON credentials with no key id"
